export const ART_CSS = "@keyframes pk-bob{0%,100%{transform:translateY(0) scale(1.03,.97)}50%{transform:translateY(-3px) scale(.98,1.02)}}\n@keyframes pk-tilt{0%,100%{transform:rotate(-5deg)}50%{transform:rotate(5deg)}}\n@keyframes pk-hop{0%,40%,100%{transform:none}8%{transform:translateY(2px) scale(1.1,.88)}20%{transform:translateY(-14px) scale(.94,1.07)}32%{transform:translateY(0) scale(1.06,.94)}}\n.alert-art .m-peek{animation:none}\n.alert-art .pk-q{animation:pk-q 1.6s ease-out infinite;opacity:0}\n@keyframes pk-q{0%,35%{opacity:0;transform:translateY(4px) scale(.4)}45%{opacity:1;transform:translateY(-2px) scale(1.15)}55%,70%{opacity:1;transform:none}85%,100%{opacity:0;transform:translateY(-4px)}}\n.alert-art .pk-spark{animation:pk-spark 1.4s ease-in-out infinite;opacity:0}\n.alert-art .pk-spark.d2{animation-delay:.6s}\n.alert-art .pk-spark.d3{animation-delay:.9s}\n@keyframes pk-spark{0%,100%{transform:scale(0);opacity:0}50%{transform:scale(1) rotate(45deg);opacity:1}}\n.alert-art .ab-wait{animation:pk-float 2.4s ease-in-out infinite,pk-ping 1.6s ease-out infinite}\n@keyframes pk-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-3px)}}\n@keyframes pk-ping{from{box-shadow:0 3px 0 #23203A,0 0 0 0 rgba(245,196,81,.9)}to{box-shadow:0 3px 0 #23203A,0 0 0 10px rgba(245,196,81,0)}}\n.alert-art .wk-shovel{animation:wk-shovel 1.8s ease-in-out infinite}\n@keyframes wk-shovel{0%{transform:none}10%{transform:rotate(6deg)}16%{transform:none}44%{transform:rotate(-70deg)}50%{transform:rotate(-82deg)}58%{transform:rotate(-74deg)}100%{transform:none}}\n.alert-art .wk-load{opacity:0;animation:wk-load 1.8s steps(1) infinite}\n@keyframes wk-load{0%,13%{opacity:0}14%,49%{opacity:1}50%,100%{opacity:0}}\n.alert-art .wk-toss{opacity:0;animation:wk-toss 1.8s linear infinite}\n@keyframes wk-toss{0%,49%{opacity:0;transform:none}50%{opacity:1;transform:none}56%{opacity:1;transform:translate(4px,-3px)}66%{opacity:1;transform:translate(9px,11px)}68%,100%{opacity:0;transform:translate(9px,13px)}}\n.alert-art .wk-flare{opacity:0;animation:wk-flare 1.8s ease-out infinite}\n@keyframes wk-flare{0%,66%{opacity:0;transform:none}72%{opacity:1;transform:translateY(-3px)}88%{opacity:.6;transform:translateY(-1px)}100%{opacity:0;transform:none}}\n.alert-art .wk-puff{opacity:0;animation:wk-puff 1.8s ease-out infinite}\n.alert-art .wk-puff.p2{animation-delay:.9s}\n@keyframes wk-puff{0%{opacity:0;transform:none}20%{opacity:.9}100%{opacity:0;transform:translate(2px,-14px)}}\n.alert-art .rb-arm{transform-origin:47px 42px;animation:rb-arm 1.8s ease-in-out infinite}\n@keyframes rb-arm{0%,12%{transform:rotate(60deg)}18%{transform:rotate(68deg)}24%{transform:rotate(60deg)}50%,58%{transform:rotate(155deg)}80%,100%{transform:rotate(60deg)}}\n.alert-art .rb-chip{opacity:0;animation:rb-chip 1.8s steps(1) infinite}\n@keyframes rb-chip{0%,19%{opacity:0}20%,53%{opacity:1}54%,100%{opacity:0}}\n.alert-art .rb-door{animation:rb-door 1.8s steps(1) infinite}\n@keyframes rb-door{0%,39%{opacity:1}40%,62%{opacity:0}63%,100%{opacity:1}}\n.alert-art .rb-flare{opacity:0;animation:rb-flare 1.8s ease-out infinite}\n@keyframes rb-flare{0%,55%{opacity:0;transform:none}60%{opacity:1;transform:translateY(-1px)}72%{opacity:.7;transform:none}80%,100%{opacity:0}}\n.alert-art .rb-puff{opacity:0;animation:rb-puff 1.8s ease-out infinite}\n.alert-art .rb-puff.p2{animation-delay:.2s}\n@keyframes rb-puff{0%,58%{opacity:0;transform:none}64%{opacity:.95}100%{opacity:0;transform:translate(2px,-14px)}}\n@media (prefers-reduced-motion: reduce){.alert-art .rb-arm,.alert-art .rb-chip,.alert-art .rb-door,.alert-art .rb-flare,.alert-art .rb-puff{animation:none}}\n@media (prefers-reduced-motion: reduce){.alert-art .pk-bob,.alert-art .pk-tilt,.alert-art .pk-hop,.alert-art .pk-q,.alert-art .pk-spark,.alert-art .ab-wait,.alert-art .wk-shovel,.alert-art .wk-load,.alert-art .wk-toss,.alert-art .wk-flare,.alert-art .wk-puff{animation:none}.pk-q,.wk-load{opacity:1}}";
